Python (pseudocode):
from redwood import RedwoodClient, RetryProfile
client = RedwoodClient(retry_profile=RetryProfile.BALANCED, idempotency_key='user-op-{{uuid}}')
resp = client.generate(prompt='hello', idempotency_key='op-1234')

# Resumable stream
stream = client.generate_stream(prompt='long', resume_token=last_token)
for chunk in stream:
    process(chunk)
// On transient disconnect: stream.resume(resume_token)
TypeScript (pseudocode):
import { Redwood, RetryProfile } from '@redwood/sdk'
const client = new Redwood({ retryProfile: RetryProfile.Balanced })
const resp = await client.generate({ prompt: 'hello' , idempotencyKey: 'op-1234' })

// Streaming with resume
const stream = client.generateStream({ prompt: 'big', onResume: (token) => save(token) })
stream.on('data', chunk => handle(chunk))
stream.on('close', () => attemptResume(savedToken))
